export const STAFF_OPERATIONS_HANDBOOK_VERSION = "2.0";
export const STAFF_OPERATIONS_HANDBOOK_TITLE = "Zest for English · Staff Operations Handbook";
export const staffOperationsHandbookHtml = "<!DOCTYPE html>\n<html lang=\"vi\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>Zest for English | Staff Operations Handbook</title>\n<style>\n  :root {\n    --blue:#1834E8;\n    --blue2:#0D25B9;\n    --yellow:#FFC400;\n    --ink:#17213A;\n    --muted:#667085;\n    --line:#DCE3F0;\n    --soft:#F5F7FC;\n    --soft-blue:#EEF2FF;\n    --soft-yellow:#FFF8D8;\n    --danger:#B42318;\n    --soft-red:#FEECEB;\n    --green:#027A48;\n    --soft-green:#ECFDF3;\n    --white:#fff;\n  }\n  *{box-sizing:border-box}\n  html{scroll-behavior:smooth}\n  body{\n    margin:0;\n    font-family:Inter,Arial,Helvetica,sans-serif;\n    color:var(--ink);\n    background:#EEF2F8;\n    line-height:1.55;\n  }\n  .app{max-width:1180px;margin:0 auto;background:#fff;min-height:100vh;box-shadow:0 10px 40px rgba(16,24,40,.10)}\n  .hero{\n    position:relative;\n    overflow:hidden;\n    padding:48px 56px 44px;\n    color:#fff;\n    background:\n      radial-gradient(circle at 88% 15%, rgba(255,196,0,.25) 0 120px, transparent 122px),\n      linear-gradient(135deg,var(--blue2),var(--blue));\n  }\n  .hero:after{\n    content:\"\";\n    position:absolute;right:-85px;bottom:-120px;width:360px;height:360px;\n    border:52px solid rgba(255,196,0,.18);border-radius:50%;\n  }\n  .brand{display:flex;align-items:center;gap:15px;position:relative;z-index:2}\n  .logo{width:76px;height:76px;border-radius:18px;object-fit:cover;box-shadow:0 8px 24px rgba(0,0,0,.18)}\n  .brand-name{font-weight:800;font-size:20px;letter-spacing:.2px}\n  .brand-tag{font-size:12px;opacity:.82;text-transform:uppercase;letter-spacing:1.8px}\n  .hero h1{font-size:42px;line-height:1.08;margin:42px 0 12px;max-width:800px;position:relative;z-index:2}\n  .hero p{max-width:760px;font-size:16px;opacity:.92;position:relative;z-index:2}\n  .hero .pill{display:inline-flex;margin-top:16px;background:var(--yellow);color:#152260;font-weight:800;padding:8px 13px;border-radius:999px;font-size:12px;position:relative;z-index:2}\n  .nav{position:sticky;top:0;z-index:20;background:rgba(255,255,255,.96);backdrop-filter:blur(10px);border-bottom:1px solid var(--line);padding:10px 22px;display:flex;gap:8px;overflow:auto}\n  .nav a{white-space:nowrap;text-decoration:none;color:var(--ink);font-size:12px;font-weight:700;padding:8px 10px;border-radius:9px}\n  .nav a:hover{background:var(--soft-blue);color:var(--blue)}\n  main{padding:36px 52px 64px}\n  section{scroll-margin-top:64px;margin-bottom:48px}\n  .section-title{display:flex;align-items:center;gap:12px;margin-bottom:18px}\n  .section-no{width:34px;height:34px;border-radius:10px;background:var(--yellow);color:#16235B;display:grid;place-items:center;font-weight:900}\n  h2{font-size:25px;margin:0;color:#15224B}\n  h3{font-size:16px;margin:0 0 9px;color:#17213A}\n  p{margin:6px 0 12px}\n  .lead{font-size:15px;color:var(--muted);max-width:860px}\n  .rule-grid,.role-grid,.metric-grid{display:grid;gap:14px}\n  .rule-grid{grid-template-columns:repeat(3,1fr)}\n  .role-grid{grid-template-columns:repeat(3,1fr)}\n  .metric-grid{grid-template-columns:repeat(4,1fr)}\n  .card{border:1px solid var(--line);border-radius:16px;padding:18px;background:#fff;box-shadow:0 3px 14px rgba(16,24,40,.04)}\n  .card.blue{background:linear-gradient(180deg,#F6F8FF,#EEF2FF);border-color:#C8D2FF}\n  .card.yellow{background:linear-gradient(180deg,#FFFDF4,#FFF8D8);border-color:#F4DEA2}\n  .rule-num{font-size:11px;color:var(--blue);font-weight:900;letter-spacing:1px;text-transform:uppercase}\n  .rule-title{font-size:16px;font-weight:800;margin:5px 0 7px}\n  .rule-copy{font-size:13px;color:var(--muted)}\n  .role-head{display:flex;align-items:center;justify-content:space-between;gap:10px;margin-bottom:12px}\n  .role-person{font-size:23px;font-weight:900;color:var(--blue)}\n  .role-title{font-size:11px;font-weight:800;color:#475467;text-transform:uppercase;letter-spacing:.7px}\n  .owner-badge{padding:6px 9px;border-radius:999px;background:var(--yellow);color:#17215A;font-size:10px;font-weight:900}\n  ul.clean{padding-left:18px;margin:8px 0 0}\n  ul.clean li{margin:5px 0;font-size:13px}\n  .not-own{margin-top:14px;padding:11px 12px;border-radius:11px;background:var(--soft-red);font-size:12px;color:#7A271A}\n  .not-own b{color:var(--danger)}\n  table{width:100%;border-collapse:separate;border-spacing:0;border:1px solid var(--line);border-radius:14px;overflow:hidden;background:#fff}\n  th{background:var(--blue);color:#fff;text-align:left;padding:11px 12px;font-size:12px}\n  td{padding:11px 12px;border-top:1px solid var(--line);vertical-align:top;font-size:12px}\n  tbody tr:nth-child(even) td{background:#FAFBFE}\n  .owner{font-weight:900;color:var(--blue)}\n  .support{color:var(--muted)}\n  .flow{display:grid;grid-template-columns:170px 1fr;gap:15px;align-items:start;margin-bottom:12px}\n  .flow-time{font-size:12px;font-weight:900;color:var(--blue);background:var(--soft-blue);padding:10px 12px;border-radius:10px;text-align:center}\n  .flow-box{border-left:3px solid var(--yellow);padding:2px 0 2px 15px}\n  .flow-box b{display:block;margin-bottom:2px}\n  .checklist{display:grid;grid-template-columns:repeat(2,1fr);gap:10px}\n  .check{display:flex;gap:10px;padding:11px 12px;border:1px solid var(--line);border-radius:11px;background:#fff;font-size:12px}\n  .check input{accent-color:var(--blue);width:17px;height:17px;flex:0 0 auto}\n  .job-block{border:1px solid var(--line);border-radius:18px;overflow:hidden;margin-bottom:18px}\n  .job-top{padding:17px 18px;background:linear-gradient(90deg,var(--blue2),var(--blue));color:#fff;display:flex;justify-content:space-between;align-items:flex-start;gap:20px}\n  .job-top h3{color:#fff;font-size:21px;margin:0}\n  .job-top .mission{font-size:12px;opacity:.9;max-width:660px}\n  .job-body{padding:18px}\n  .job-cols{display:grid;grid-template-columns:1.25fr 1fr 1fr;gap:18px}\n  .mini-title{font-size:11px;color:var(--blue);font-weight:900;text-transform:uppercase;letter-spacing:.8px;margin-bottom:7px}\n  .kpi{font-size:12px;padding:7px 9px;border-radius:9px;background:var(--soft-green);color:#05603A;margin:5px 0}\n  .single-form{border:2px solid var(--blue);border-radius:20px;padding:20px;background:linear-gradient(180deg,#fff,#F8FAFF)}\n  .form-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:10px;margin-bottom:12px}\n  label{font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.6px;color:#475467;display:block;margin-bottom:5px}\n  input[type=text], input[type=date], input[type=time], select, textarea{\n    width:100%;border:1px solid #C9D2E4;border-radius:9px;padding:9px 10px;font:inherit;font-size:12px;color:var(--ink);background:#fff;\n  }\n  textarea{min-height:78px;resize:vertical}\n  .two-col{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n  .three-col{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}\n  .form-block{margin-top:11px}\n  .note{padding:12px 14px;border-radius:11px;background:var(--soft-yellow);font-size:12px;color:#594A00}\n  .accountability{display:grid;grid-template-columns:repeat(3,1fr);gap:12px}\n  .severity{padding:16px;border-radius:14px;border:1px solid var(--line)}\n  .severity .tag{font-size:10px;font-weight:900;text-transform:uppercase;letter-spacing:.7px}\n  .severity h3{font-size:16px;margin:5px 0}\n  .severity p{font-size:12px;color:var(--muted)}\n  .severity.l1{background:#F8FAFC}\n  .severity.l2{background:var(--soft-yellow);border-color:#F0D779}\n  .severity.l3{background:var(--soft-red);border-color:#F4B4AF}\n  .do-dont{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n  .do,.dont{padding:15px;border-radius:14px}\n  .do{background:var(--soft-green);border:1px solid #A6F4C5}\n  .dont{background:var(--soft-red);border:1px solid #F9B1AA}\n  .quick-ref{position:relative;overflow:hidden}\n  .quick-ref:before{content:\"\";position:absolute;right:-60px;top:-60px;width:180px;height:180px;border-radius:50%;background:rgba(255,196,0,.18)}\n  .manager-grid{display:grid;grid-template-columns:1fr 1fr;gap:16px}\n  .metric{border:1px solid var(--line);border-radius:14px;padding:15px}\n  .metric .big{font-size:24px;font-weight:900;color:var(--blue)}\n  .metric .small{font-size:11px;color:var(--muted)}\n  .action-row{display:flex;justify-content:flex-end;gap:8px;margin-top:14px}\n  button{border:0;border-radius:10px;padding:10px 14px;font-weight:800;cursor:pointer}\n  .btn-primary{background:var(--blue);color:#fff}\n  .btn-secondary{background:#E9EDF7;color:#344054}\n  footer{padding:26px 52px;background:#101B57;color:#fff;display:flex;align-items:center;justify-content:space-between;gap:20px}\n  footer img{width:44px;height:44px;border-radius:10px}\n  footer .footbrand{display:flex;align-items:center;gap:11px}\n  footer small{opacity:.65}\n  .print-note{font-size:11px;color:var(--muted);margin-top:8px}\n  @media(max-width:900px){\n    .hero{padding:34px 24px} .hero h1{font-size:34px}\n    main{padding:30px 22px 50px}\n    .rule-grid,.role-grid,.metric-grid,.accountability,.job-cols,.two-col,.three-col,.manager-grid,.form-grid{grid-template-columns:1fr}\n    .checklist{grid-template-columns:1fr}\n    .flow{grid-template-columns:1fr}\n    footer{padding:22px}\n  }\n  @media print{\n    body{background:#fff}\n    .app{box-shadow:none;max-width:none}\n    .nav,.action-row,.print-note{display:none!important}\n    .hero{padding:26px 32px}\n    .hero h1{font-size:32px;margin-top:22px}\n    main{padding:26px 32px}\n    section{break-inside:auto;margin-bottom:30px}\n    .job-block,.single-form,.card,.severity,.manager-grid,table{break-inside:avoid}\n    footer{padding:16px 32px}\n    @page{size:A4;margin:10mm}\n  }\n</style>\n</head>\n<body>\n<div class=\"app\">\n\n<header class=\"hero\">\n  <div class=\"brand\">\n    <img class=\"logo\" src=\"data:image/png;base64,\" alt=\"Zest for English logo\">\n    <div>\n      <div class=\"brand-name\">Zest for English</div>\n      <div class=\"brand-tag\">Staff Operations Handbook</div>\n    </div>\n  </div>\n  <h1>Ít biểu mẫu hơn.<br>Công việc rõ hơn.</h1>\n  <p>Bộ quy chuẩn vận hành dành cho đội ngũ nhỏ: mỗi việc chỉ có một owner chính, mỗi người biết chính xác mình phải làm gì hằng ngày, và toàn bộ đội chỉ dùng một Daily Work Log duy nhất.</p>\n  <span class=\"pill\">VERSION 2.0 · SMALL TEAM OPERATING SYSTEM</span>\n</header>\n\n<nav class=\"nav\">\n  <a href=\"#rules\">Nguyên tắc</a>\n  <a href=\"#roles\">Vai trò</a>\n  <a href=\"#ownership\">Ai sở hữu việc gì?</a>\n  <a href=\"#jd\">JD & Checklist</a>\n  <a href=\"#daily\">Nhịp làm việc</a>\n  <a href=\"#report\">1 Daily Log</a>\n  <a href=\"#accountability\">Trách nhiệm</a>\n  <a href=\"#manager\">Manager Review</a>\n</nav>\n\n<main>\n\n<section id=\"rules\">\n  <div class=\"section-title\"><span class=\"section-no\">01</span><h2>6 nguyên tắc làm việc</h2></div>\n  <p class=\"lead\">Không cần nhiều quy trình. Chỉ cần mọi người tuân thủ cùng một cách làm việc.</p>\n  <div class=\"rule-grid\">\n    <div class=\"card\"><div class=\"rule-num\">Rule 01</div><div class=\"rule-title\">Một việc = một owner</div><div class=\"rule-copy\">Người khác có thể hỗ trợ, nhưng không tự giành việc, tự hứa hoặc tự đổi quyết định của owner.</div></div>\n    <div class=\"card\"><div class=\"rule-num\">Rule 02</div><div class=\"rule-title\">Đã nhận việc phải phản hồi</div><div class=\"rule-copy\">Không im lặng. Nếu chưa xử lý xong, ít nhất phải báo đã nhận + thời gian dự kiến cập nhật.</div></div>\n    <div class=\"card\"><div class=\"rule-num\">Rule 03</div><div class=\"rule-title\">Không để việc “nằm trong chat”</div><div class=\"rule-copy\">Lịch, lead, placement, complaint, phí và issue quan trọng phải được cập nhật vào nơi theo dõi chung.</div></div>\n    <div class=\"card\"><div class=\"rule-num\">Rule 04</div><div class=\"rule-title\">Trễ phải báo trước hạn</div><div class=\"rule-copy\">Báo sau khi đã trễ không được xem là quản trị công việc. Có nguy cơ trễ → báo ngay.</div></div>\n    <div class=\"card\"><div class=\"rule-num\">Rule 05</div><div class=\"rule-title\">Check-in phải đúng thực tế</div><div class=\"rule-copy\">Không check-in hộ, không tự sửa giờ, không khai báo giờ làm việc khác với thực tế.</div></div>\n    <div class=\"card\"><div class=\"rule-num\">Rule 06</div><div class=\"rule-title\">Done = đã đóng vòng</div><div class=\"rule-copy\">Đã làm xong + đã cập nhật hệ thống + đã báo người liên quan + không còn việc treo không owner.</div></div>\n  </div>\n</section>\n\n<section id=\"roles\">\n  <div class=\"section-title\"><span class=\"section-no\">02</span><h2>3 người · 3 vùng trách nhiệm</h2></div>\n  <p class=\"lead\">Cách phân vai dưới đây nhằm chấm dứt tình trạng Khang và Thịnh cùng nhảy vào một việc hoặc làm những việc không thuộc owner của mình.</p>\n  <div class=\"role-grid\">\n    <div class=\"card blue\">\n      <div class=\"role-head\"><div><div class=\"role-person\">THỊNH</div><div class=\"role-title\">Scheduling & Student Operations</div></div><span class=\"owner-badge\">OWNER: LỊCH</span></div>\n      <h3>Nhiệm vụ số 1</h3>\n      <p style=\"font-size:13px\">Đảm bảo mọi lớp đang học đều có lịch rõ ràng và học viên biết buổi tiếp theo của mình.</p>\n      <ul class=\"clean\">\n        <li>Chốt/deal lịch với học viên.</li>\n        <li>Xử lý đổi, huỷ, học bù.</li>\n        <li>Theo dõi lớp chưa có lịch hoặc có nguy cơ mất buổi.</li>\n        <li>Cập nhật lịch chính thức và gửi xác nhận cho HV.</li>\n      </ul>\n      <div class=\"not-own\"><b>Không tự làm:</b> đánh giá GV, đổi GV, xử lý học thuật, báo phí hoặc placement.</div>\n    </div>\n    <div class=\"card yellow\">\n      <div class=\"role-head\"><div><div class=\"role-person\">KHANG</div><div class=\"role-title\">Academic & Teacher Quality</div></div><span class=\"owner-badge\">OWNER: HỌC THUẬT</span></div>\n      <h3>Nhiệm vụ số 1</h3>\n      <p style=\"font-size:13px\">Đảm bảo GV phù hợp, chất lượng lớp ổn và hệ thống học thuật đủ chuẩn để vận hành.</p>\n      <ul class=\"clean\">\n        <li>Quản lý GV và teacher availability.</li>\n        <li>Dự giờ, feedback, theo dõi chất lượng.</li>\n        <li>Phát triển/cập nhật test, học liệu, sản phẩm học thuật.</li>\n        <li>Academic onboarding cho HV.</li>\n      </ul>\n      <div class=\"not-own\"><b>Không tự làm:</b> deal/chốt lịch trực tiếp với HV, thay đổi master schedule, báo phí hoặc chăm lead.</div>\n    </div>\n    <div class=\"card blue\">\n      <div class=\"role-head\"><div><div class=\"role-person\">MAI</div><div class=\"role-title\">Customer Success & Admissions Operations</div></div><span class=\"owner-badge\">OWNER: KHÁCH HÀNG</span></div>\n      <h3>Nhiệm vụ số 1</h3>\n      <p style=\"font-size:13px\">Không để lead hoặc khách hàng bị bỏ quên; placement, dữ liệu và phí luôn có trạng thái rõ.</p>\n      <ul class=\"clean\">\n        <li>CSKH và chăm sóc leads.</li>\n        <li>Book placement test và nhắc lịch.</li>\n        <li>Tổ chức thi thử về mặt logistics.</li>\n        <li>Nhập liệu, tìm khách hàng, đối soát và báo phí.</li>\n      </ul>\n      <div class=\"not-own\"><b>Không tự làm:</b> tự chốt đổi lịch lớp, kết luận chuyên môn hoặc tự sửa test/học liệu.</div>\n    </div>\n  </div>\n</section>\n\n<section id=\"ownership\">\n  <div class=\"section-title\"><span class=\"section-no\">03</span><h2>Ai sở hữu việc gì?</h2></div>\n  <p class=\"lead\">Chỉ cần nhớ bảng này. Nếu không phải owner, nhiệm vụ của bạn là chuyển đúng người và cung cấp thông tin cần thiết.</p>\n  <table>\n    <thead><tr><th>Tình huống</th><th>Owner</th><th>Người hỗ trợ</th><th>Flow chuẩn</th></tr></thead>\n    <tbody>\n      <tr><td>HV muốn đổi / huỷ / học bù</td><td class=\"owner\">THỊNH</td><td class=\"support\">Mai nhận tin; Khang hỗ trợ nếu liên quan GV</td><td>Nhận yêu cầu → Thịnh xử lý → hỏi Khang nếu cần GV → Thịnh chốt lại với HV.</td></tr>\n      <tr><td>GV nghỉ / không thể dạy</td><td class=\"owner\">KHANG</td><td class=\"support\">Thịnh</td><td>Khang xác nhận phương án GV → Thịnh xử lý lịch và communication với HV.</td></tr>\n      <tr><td>HV complain chất lượng GV/lớp</td><td class=\"owner\">KHANG</td><td class=\"support\">Mai tiếp nhận & log</td><td>Mai acknowledge → Khang review → Khang ra academic action → Thịnh chỉ tham gia nếu phải đổi lịch.</td></tr>\n      <tr><td>Lead / CSKH / follow-up</td><td class=\"owner\">MAI</td><td class=\"support\">Khang khi cần tư vấn học thuật</td><td>Mai giữ owner conversation từ đầu đến next action.</td></tr>\n      <tr><td>Placement test</td><td class=\"owner\">MAI</td><td class=\"support\">Khang về test/academic</td><td>Mai book & nhắc → Khang bảo đảm nội dung/tiêu chí → Mai theo dõi next step.</td></tr>\n      <tr><td>Test / học liệu / academic product</td><td class=\"owner\">KHANG</td><td class=\"support\">GV / Manager</td><td>Khang phát triển, QA, version control và đưa vào sử dụng.</td></tr>\n      <tr><td>Thi thử</td><td class=\"owner\">MAI: logistics</td><td class=\"support\">Khang: academic QA</td><td>Mai lo candidate/list/lịch → Khang lo đề, tiêu chí chấm, chất lượng.</td></tr>\n      <tr><td>Phí / đối soát / công nợ</td><td class=\"owner\">MAI</td><td class=\"support\">Manager/Kế toán nếu có</td><td>Mai kiểm tra, báo phí và flag sai lệch.</td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"jd\">\n  <div class=\"section-title\"><span class=\"section-no\">04</span><h2>JD + checklist thực tế</h2></div>\n  <p class=\"lead\">Không tách thêm biểu mẫu. Mỗi người chỉ cần nhìn đúng block của mình để biết hôm nay phải làm gì.</p>\n\n  <div class=\"job-block\">\n    <div class=\"job-top\">\n      <div><h3>THỊNH · Scheduling & Student Operations</h3><div class=\"mission\">Mission: Không để lớp active nào rơi vào trạng thái “không biết buổi tiếp theo học khi nào” vì lỗi vận hành.</div></div>\n      <span class=\"owner-badge\">LỊCH HỌC</span>\n    </div>\n    <div class=\"job-body\">\n      <div class=\"job-cols\">\n        <div>\n          <div class=\"mini-title\">Hằng ngày phải làm</div>\n          <div class=\"checklist\">\n            <label class=\"check\"><input type=\"checkbox\">Check lịch hôm nay + 48 giờ tới.</label>\n            <label class=\"check\"><input type=\"checkbox\">List lớp chưa confirmed/chưa có next session.</label>\n            <label class=\"check\"><input type=\"checkbox\">Xử lý toàn bộ yêu cầu đổi/huỷ lịch.</label>\n            <label class=\"check\"><input type=\"checkbox\">Hỏi Khang nếu cần teacher availability.</label>\n            <label class=\"check\"><input type=\"checkbox\">Update master schedule ngay khi chốt.</label>\n            <label class=\"check\"><input type=\"checkbox\">Gửi xác nhận lịch cho HV.</label>\n          </div>\n        </div>\n        <div>\n          <div class=\"mini-title\">Kết quả phải nhìn thấy</div>\n          <div class=\"kpi\">100% lớp active có next session hoặc trạng thái rõ.</div>\n          <div class=\"kpi\">Không mất buổi do bỏ sót lịch nội bộ.</div>\n          <div class=\"kpi\">Yêu cầu đổi lịch được acknowledge trong giờ làm việc.</div>\n        </div>\n        <div>\n          <div class=\"mini-title\">Không được tự làm</div>\n          <ul class=\"clean\">\n            <li>Tự đổi GV.</li>\n            <li>Tự đánh giá chất lượng GV.</li>\n            <li>Tự xử lý học thuật.</li>\n            <li>Tự báo/đổi phí.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"job-block\">\n    <div class=\"job-top\">\n      <div><h3>KHANG · Academic & Teacher Quality</h3><div class=\"mission\">Mission: GV đúng năng lực, lớp đúng chất lượng, học liệu/test đủ chuẩn; không làm thay vai trò scheduling.</div></div>\n      <span class=\"owner-badge\">GV & HỌC THUẬT</span>\n    </div>\n    <div class=\"job-body\">\n      <div class=\"job-cols\">\n        <div>\n          <div class=\"mini-title\">Hằng ngày phải làm</div>\n          <div class=\"checklist\">\n            <label class=\"check\"><input type=\"checkbox\">Review GV nghỉ/bận/issue ảnh hưởng lớp.</label>\n            <label class=\"check\"><input type=\"checkbox\">Phản hồi request GV từ Thịnh.</label>\n            <label class=\"check\"><input type=\"checkbox\">Review academic complaint mới.</label>\n            <label class=\"check\"><input type=\"checkbox\">Thực hiện observation/QA theo kế hoạch.</label>\n            <label class=\"check\"><input type=\"checkbox\">Theo dõi feedback/corrective action GV.</label>\n            <label class=\"check\"><input type=\"checkbox\">Tiến độ test/học liệu/onboarding.</label>\n          </div>\n        </div>\n        <div>\n          <div class=\"mini-title\">Kết quả phải nhìn thấy</div>\n          <div class=\"kpi\">Teacher availability đủ rõ để Thịnh chốt lịch.</div>\n          <div class=\"kpi\">Observation có feedback/action cụ thể.</div>\n          <div class=\"kpi\">Test/học liệu chính thức có version & QA.</div>\n        </div>\n        <div>\n          <div class=\"mini-title\">Không được tự làm</div>\n          <ul class=\"clean\">\n            <li>Không deal giờ học trực tiếp với HV.</li>\n            <li>Không tự đổi master schedule.</li>\n            <li>Không chăm lead thay Mai.</li>\n            <li>Không báo hoặc cam kết phí.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"job-block\">\n    <div class=\"job-top\">\n      <div><h3>MAI · Customer Success & Admissions Operations</h3><div class=\"mission\">Mission: Không để khách hàng hoặc lead bị bỏ quên; placement, dữ liệu và phí đều có trạng thái + next action.</div></div>\n      <span class=\"owner-badge\">CSKH & LEAD</span>\n    </div>\n    <div class=\"job-body\">\n      <div class=\"job-cols\">\n        <div>\n          <div class=\"mini-title\">Hằng ngày phải làm</div>\n          <div class=\"checklist\">\n            <label class=\"check\"><input type=\"checkbox\">Clear lead/inquiry mới.</label>\n            <label class=\"check\"><input type=\"checkbox\">Follow-up lead đến hạn.</label>\n            <label class=\"check\"><input type=\"checkbox\">Update CRM/data quan trọng.</label>\n            <label class=\"check\"><input type=\"checkbox\">Review placement + reminders.</label>\n            <label class=\"check\"><input type=\"checkbox\">Route complaint đúng owner.</label>\n            <label class=\"check\"><input type=\"checkbox\">Đối soát phí + task thi thử.</label>\n          </div>\n        </div>\n        <div>\n          <div class=\"mini-title\">Kết quả phải nhìn thấy</div>\n          <div class=\"kpi\">100% lead có status + next action.</div>\n          <div class=\"kpi\">Placement booking không bị bỏ quên.</div>\n          <div class=\"kpi\">Phí/dữ liệu sai lệch được flag trong ngày.</div>\n        </div>\n        <div>\n          <div class=\"mini-title\">Không được tự làm</div>\n          <ul class=\"clean\">\n            <li>Không tự đổi lịch lớp.</li>\n            <li>Không kết luận chất lượng GV.</li>\n            <li>Không sửa test/học liệu.</li>\n            <li>Không hứa ưu đãi ngoài thẩm quyền.</li>\n          </ul>\n        </div>\n      </div>\n    </div>\n  </div>\n</section>\n\n<section id=\"daily\">\n  <div class=\"section-title\"><span class=\"section-no\">05</span><h2>Một ngày làm việc chuẩn</h2></div>\n  <div class=\"flow\">\n    <div class=\"flow-time\">ĐẦU CA · 15 PHÚT</div>\n    <div class=\"flow-box\"><b>Check-in + xác định 3 kết quả phải hoàn thành.</b><span class=\"lead\">Không liệt kê 15 việc nhỏ. Chỉ ghi 3 outcome quan trọng nhất và case nào đang có rủi ro.</span></div>\n  </div>\n  <div class=\"flow\">\n    <div class=\"flow-time\">TRONG CA</div>\n    <div class=\"flow-box\"><b>Làm theo đúng owner và cập nhật ngay khi trạng thái đổi.</b><span class=\"lead\">Không đợi cuối ngày mới update lịch/CRM/placement.</span></div>\n  </div>\n  <div class=\"flow\">\n    <div class=\"flow-time\">KHI CÓ RỦI RO</div>\n    <div class=\"flow-box\"><b>Báo trước khi trễ.</b><span class=\"lead\">Nêu rõ: việc gì đang kẹt, đang chờ ai, ảnh hưởng gì, khi nào update tiếp.</span></div>\n  </div>\n  <div class=\"flow\">\n    <div class=\"flow-time\">CUỐI CA · 10 PHÚT</div>\n    <div class=\"flow-box\"><b>Update một Daily Work Log duy nhất.</b><span class=\"lead\">Đã làm gì, còn gì đang mở, ai owner tiếp theo, deadline nào cần nhớ.</span></div>\n  </div>\n\n  <div class=\"do-dont\" style=\"margin-top:18px\">\n    <div class=\"do\"><h3>✓ Được xem là “done” khi</h3><ul class=\"clean\"><li>Việc đã thực sự hoàn thành.</li><li>Hệ thống/lịch/CRM đã update.</li><li>Người liên quan đã được báo.</li><li>Nếu còn việc, owner + deadline đã rõ.</li></ul></div>\n    <div class=\"dont\"><h3>✕ Chưa được xem là “done” khi</h3><ul class=\"clean\"><li>“Em đã nhắn rồi” nhưng chưa có follow-up.</li><li>Lịch đã chốt nhưng chưa update.</li><li>Đã chuyển việc nhưng không handover.</li><li>Biết có nguy cơ trễ nhưng không báo.</li></ul></div>\n  </div>\n</section>\n\n<section id=\"report\">\n  <div class=\"section-title\"><span class=\"section-no\">06</span><h2>Chỉ dùng 1 Daily Work Log</h2></div>\n  <p class=\"lead\">Đây là biểu mẫu duy nhất cần dùng hằng ngày cho cả Thịnh, Khang và Mai. Có thể copy các trường này vào Google Form/Sheet hoặc dùng trực tiếp file HTML nội bộ.</p>\n\n  <div class=\"single-form\" id=\"dailyLog\">\n    <div class=\"form-grid\">\n      <div><label>Ngày</label><input type=\"date\" id=\"date\"></div>\n      <div><label>Nhân sự</label><select id=\"name\"><option>Thịnh</option><option>Khang</option><option>Mai</option></select></div>\n      <div><label>Check-in thực tế</label><input type=\"time\" id=\"checkin\"></div>\n      <div><label>Check-out thực tế</label><input type=\"time\" id=\"checkout\"></div>\n    </div>\n\n    <div class=\"three-col\">\n      <div class=\"form-block\"><label>Outcome 1 hôm nay</label><textarea id=\"o1\" placeholder=\"Kết quả phải đạt, không chỉ ghi tên task\"></textarea></div>\n      <div class=\"form-block\"><label>Outcome 2 hôm nay</label><textarea id=\"o2\"></textarea></div>\n      <div class=\"form-block\"><label>Outcome 3 hôm nay</label><textarea id=\"o3\"></textarea></div>\n    </div>\n\n    <div class=\"two-col\">\n      <div class=\"form-block\"><label>Đã hoàn thành hôm nay</label><textarea id=\"done\" placeholder=\"Việc + kết quả + evidence/link nếu có\"></textarea></div>\n      <div class=\"form-block\"><label>Việc còn mở / rủi ro / handover</label><textarea id=\"open\" placeholder=\"Case | Status | Next action | Owner | Deadline\"></textarea></div>\n    </div>\n\n    <div class=\"two-col\">\n      <div class=\"form-block\"><label>Delay / SLA breach (nếu có)</label><textarea id=\"delay\" placeholder=\"Vì sao trễ? Ảnh hưởng? Cách khắc phục?\"></textarea></div>\n      <div class=\"form-block\"><label>3 ưu tiên cho ngày mai</label><textarea id=\"tomorrow\"></textarea></div>\n    </div>\n\n    <div class=\"action-row\">\n      <button class=\"btn-secondary\" onclick=\"clearLog()\">Xoá nội dung</button>\n      <button class=\"btn-primary\" onclick=\"window.print()\">In / Save PDF</button>\n    </div>\n    <div class=\"print-note\">File này tự lưu nội dung Daily Log trên trình duyệt đang dùng. Không thay thế database/CRM nếu đơn vị đã có hệ thống chính thức.</div>\n  </div>\n</section>\n\n<section id=\"accountability\">\n  <div class=\"section-title\"><span class=\"section-no\">07</span><h2>Accountability: đơn giản nhưng rõ</h2></div>\n  <p class=\"lead\">Không cần Incident Form riêng cho mọi lỗi. Manager chỉ cần ghi lỗi vào một bảng chung khi lỗi có ảnh hưởng thực tế hoặc lặp lại.</p>\n  <div class=\"accountability\">\n    <div class=\"severity l1\">\n      <div class=\"tag\">LEVEL 1 · NHẮC NHỞ</div>\n      <h3>Lỗi nhỏ, chưa ảnh hưởng khách</h3>\n      <p>Ví dụ: quên update nhưng tự phát hiện và sửa ngay; trễ nội bộ ngắn; checklist thiếu.</p>\n      <b>Action:</b> nhắc + sửa trong ngày.\n    </div>\n    <div class=\"severity l2\">\n      <div class=\"tag\">LEVEL 2 · PERFORMANCE ISSUE</div>\n      <h3>Đã ảnh hưởng vận hành</h3>\n      <p>Ví dụ: phản hồi HV/lead trễ, bỏ follow-up, sai lịch/sai dữ liệu gây phiền hà.</p>\n      <b>Action:</b> ghi nhận + corrective action + theo dõi tái phạm.\n    </div>\n    <div class=\"severity l3\">\n      <div class=\"tag\">LEVEL 3 · SERIOUS</div>\n      <h3>Ảnh hưởng lớp, khách hoặc integrity</h3>\n      <p>Ví dụ: mất buổi do bỏ sót, fake check-in, che giấu lỗi, tự quyết ngoài thẩm quyền gây thiệt hại.</p>\n      <b>Action:</b> manager review + PIP/kỷ luật theo quy chế áp dụng.\n    </div>\n  </div>\n\n  <div class=\"note\" style=\"margin-top:14px\">\n    <b>Về “10% trách nhiệm”:</b> nên dùng như một phần của đánh giá hiệu suất hoặc performance bonus theo quy chế đã ban hành, không nên tự động chuyển mỗi lỗi thành “trừ 10% lương cơ bản”. Với team nhỏ, điều quan trọng nhất là xác định đúng owner, evidence, impact và lỗi có lặp lại hay không.\n  </div>\n\n  <h3 style=\"margin-top:20px\">Manager chỉ cần một bảng Accountability Log chung</h3>\n  <table>\n    <thead><tr><th>Ngày</th><th>Nhân sự</th><th>Lỗi / sự cố</th><th>Level</th><th>Ảnh hưởng</th><th>Corrective action</th><th>Deadline</th></tr></thead>\n    <tbody>\n      <tr><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td></tr>\n      <tr><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td></tr>\n      <tr><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td><td contenteditable=\"true\"></td></tr>\n    </tbody>\n  </table>\n</section>\n\n<section id=\"manager\">\n  <div class=\"section-title\"><span class=\"section-no\">08</span><h2>Manager chỉ cần kiểm 5 thứ</h2></div>\n  <div class=\"metric-grid\">\n    <div class=\"metric\"><div class=\"big\">01</div><b>Attendance</b><div class=\"small\">Ai đi trễ, về sớm, check-in bất thường?</div></div>\n    <div class=\"metric\"><div class=\"big\">02</div><b>Classes</b><div class=\"small\">Có lớp nào chưa có lịch / có nguy cơ mất buổi?</div></div>\n    <div class=\"metric\"><div class=\"big\">03</div><b>Customers</b><div class=\"small\">Có lead/HV/complaint nào đang bị bỏ quên?</div></div>\n    <div class=\"metric\"><div class=\"big\">04</div><b>Teachers</b><div class=\"small\">Có GV/quality issue nào ảnh hưởng delivery?</div></div>\n  </div>\n  <div class=\"metric\" style=\"margin-top:12px\">\n    <div class=\"big\">05</div><b>Ownership</b>\n    <div class=\"small\">Có việc nào đang bị Khang–Thịnh–Mai cùng làm, không ai làm, hoặc một người đang làm sai vùng trách nhiệm không?</div>\n  </div>\n\n  <div class=\"manager-grid\" style=\"margin-top:18px\">\n    <div class=\"card quick-ref\">\n      <h3>Daily review · 10 phút</h3>\n      <ul class=\"clean\">\n        <li>Check bất thường attendance.</li>\n        <li>Check case đỏ trong 24–48 giờ.</li>\n        <li>Check ai không nộp Daily Log.</li>\n        <li>Chốt owner cho việc đang bị “trôi”.</li>\n      </ul>\n    </div>\n    <div class=\"card quick-ref\">\n      <h3>Weekly review · 30 phút</h3>\n      <ul class=\"clean\">\n        <li>3 việc làm tốt trong tuần.</li>\n        <li>3 lỗi/rủi ro quan trọng.</li>\n        <li>Lỗi nào đang lặp lại?</li>\n        <li>Tuần tới ai chịu trách nhiệm gì?</li>\n      </ul>\n    </div>\n  </div>\n</section>\n\n</main>\n\n<footer>\n  <div class=\"footbrand\">\n    <img src=\"data:image/png;base64,\" alt=\"\">\n    <div><b>Zest for English</b><br><small>Staff Operations Handbook · Internal Use</small></div>\n  </div>\n  <small>Clear roles · Clear ownership · Clear follow-through</small>\n</footer>\n\n</div>\n\n\n\n<div style=\"max-width:1180px;margin:0 auto;padding:12px 22px;background:#FFF8D8;border-top:1px solid #F4DEA2;color:#594A00;font:600 12px Inter,Arial,sans-serif\">\n  Trong ZE CenterOS, Daily Work Log chính thức được lưu vào database tại module Staff Operations. Form trong handbook này được giữ để tham chiếu nội dung/trường dữ liệu.\n</div>\n</body>\n</html>\n";
